     1→/**
     2→ * Image Generation Service
     3→ * Client for OpenRouter API using Gemini 2.5 Flash Preview Image model for outfit visualization
     4→ *
     5→ * Features:
     6→ * - Fashion-specific prompt engineering
     7→ * - Error handling with retries
     8→ * - Timeout protection
     9→ * - Rate limiting awareness
    10→ */
    11→
    12→import type { ImageGenerationRequest, ImageGenerationResponse } from '../types/image-types';
    13→
    14→/**
    15→ * OpenRouter API configuration
    16→ */
    17→const OPENROUTER_CONFIG = {
    18→  /** OpenRouter API base URL */
    19→  baseUrl: 'https://openrouter.ai/api/v1',
    20→  /**
    21→   * Model ID for Gemini 3 Pro Image Preview - Nano Banana Pro (text-to-image capable)
    22→   * Google's most advanced image-generation and editing model
    23→   */
    24→  model: 'google/gemini-2.5-flash-image',
    25→  /** Request timeout in milliseconds */
    26→  timeout: 30000,
    27→  /** Maximum retry attempts on failure */
    28→  maxRetries: 2,
    29→  /** Exponential backoff base delay (ms) */
    30→  retryDelay: 1000,
    31→};
    32→
    33→/**
    34→ * OpenRouter Image Generation Client
    35→ * Handles communication with OpenRouter API for outfit image generation
    36→ */
    37→export class OpenRouterImageClient {
    38→  private apiKey: string;
    39→  private requestCount: number = 0;
    40→  private lastRequestTime: number = 0;
    41→
    42→  /**
    43→   * Creates a new OpenRouter image client
    44→   *
    45→   * @param apiKey - OpenRouter API key
    46→   * @throws Error if API key is not provided
    47→   */
    48→  constructor(apiKey: string) {
    49→    if (!apiKey || typeof apiKey !== 'string' || apiKey.trim() === '') {
    50→      throw new Error('OpenRouter API key is required');
    51→    }
    52→    this.apiKey = apiKey;
    53→  }
    54→
    55→  /**
    56→   * Configuration for fitting model generation
    57→   */
    58→  private static readonly FITTING_MODEL_CONFIG = {
    59→    /** Extended timeout for fitting model generation (60 seconds) */
    60→    timeout: 60000,
    61→  };
    62→
    63→  /**
    64→   * Generates an outfit image from description using Gemini 2.5 Flash Preview
    65→   *
    66→   * @param description - Outfit description extracted from conversation
    67→   * @param options - Optional style parameters
    68→   * @returns Promise resolving to image generation response
    69→   *
    70→   * @example
    71→   * const client = new OpenRouterImageClient(apiKey);
    72→   * const response = await client.generateOutfitImage(
    73→   *   "White shirt with black pants for business meeting",
    74→   *   { style: { composition: 'flat-lay' } }
    75→   * );
    76→   */
    77→  async generateOutfitImage(
    78→    description: string,
    79→    options?: ImageGenerationRequest['style']
    80→  ): Promise<ImageGenerationResponse> {
    81→    // Validate input
    82→    if (!description || typeof description !== 'string' || description.trim() === '') {
    83→      return {
    84→        success: false,
    85→        error: 'INVALID_DESCRIPTION',
    86→        message: 'Outfit description is required',
    87→      };
    88→    }
    89→
    90→    // Check client-side rate limiting (basic protection)
    91→    if (!this.checkRateLimit()) {
    92→      return {
    93→        success: false,
    94→        error: 'RATE_LIMITED',
    95→        message: 'Too many requests. Please wait a moment before trying again.',
    96→      };
    97→    }
    98→
    99→    // Attempt generation with retries
   100→    let lastError: Error | null = null;
   101→
   102→    for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
   103→      try {
   104→        if (attempt > 0) {
   105→          // Exponential backoff delay
   106→          const delay = OPENROUTER_CONFIG.retryDelay * Math.pow(2, attempt - 1);
   107→          await this.sleep(delay);
   108→          console.log(`[ImageGen] Retry attempt ${attempt}/${OPENROUTER_CONFIG.maxRetries}`);
   109→        }
   110→
   111→        const result = await this.makeRequest(description, options);
   112→        return result;
   113→      } catch (error) {
   114→        lastError = error as Error;
   115→        console.error(`[ImageGen] Attempt ${attempt + 1} failed:`, error);
   116→
   117→        // Don't retry on certain errors
   118→        if (this.isNonRetryableError(error)) {
   119→          break;
   120→        }
   121→      }
   122→    }
   123→
   124→    // All retries failed
   125→    return {
   126→      success: false,
   127→      error: 'GENERATION_FAILED',
   128→      message: 'Unable to generate image. Please try again later.',
   129→    };
   130→  }
   131→
   132→  /**
   133→   * Generates a fitting model image using a reference image for face-matching.
   134→   * Uses OpenRouter's multimodal content format to pass the reference image.
   135→   *
   136→   * @param prompt - Fitting model generation prompt with style requirements
   137→   * @param referenceImageBase64 - Base64 encoded reference image (with data URL prefix)
   138→   * @returns Promise resolving to image generation response
   139→   *
   140→   * @example
   141→   * const client = new OpenRouterImageClient(apiKey);
   142→   * const response = await client.generateFittingModelImage(
   143→   *   "Create a photorealistic fitting model...",
   144→   *   "data:image/jpeg;base64,/9j/4AAQ..."
   145→   * );
   146→   */
   147→  async generateFittingModelImage(
   148→    prompt: string,
   149→    referenceImageBase64: string
   150→  ): Promise<ImageGenerationResponse> {
   151→    // Validate inputs
   152→    if (!prompt || typeof prompt !== 'string' || prompt.trim() === '') {
   153→      return {
   154→        success: false,
   155→        error: 'INVALID_PROMPT',
   156→        message: 'Fitting model prompt is required',
   157→      };
   158→    }
   159→
   160→    if (!referenceImageBase64 || typeof referenceImageBase64 !== 'string' || referenceImageBase64.trim() === '') {
   161→      return {
   162→        success: false,
   163→        error: 'INVALID_REFERENCE_IMAGE',
   164→        message: 'Reference image is required for fitting model generation',
   165→      };
   166→    }
   167→
   168→    if (!referenceImageBase64.startsWith('data:image/')) {
   169→      return {
   170→        success: false,
   171→        error: 'INVALID_REFERENCE_IMAGE_FORMAT',
   172→        message: 'Reference image must be a base64 data URL (e.g., data:image/jpeg;base64,...)',
   173→      };
   174→    }
   175→
   176→    // Check client-side rate limiting
   177→    if (!this.checkRateLimit()) {
   178→      return {
   179→        success: false,
   180→        error: 'RATE_LIMITED',
   181→        message: 'Too many requests. Please wait a moment before trying again.',
   182→      };
   183→    }
   184→
   185→    // Attempt generation with retries
   186→    let lastError: Error | null = null;
   187→
   188→    for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
   189→      try {
   190→        if (attempt > 0) {
   191→          // Exponential backoff delay
   192→          const delay = OPENROUTER_CONFIG.retryDelay * Math.pow(2, attempt - 1);
   193→          await this.sleep(delay);
   194→          console.log(`[ImageGen] Fitting model retry attempt ${attempt}/${OPENROUTER_CONFIG.maxRetries}`);
   195→        }
   196→
   197→        const result = await this.makeFittingModelRequest(prompt, referenceImageBase64);
   198→        return result;
   199→      } catch (error) {
   200→        lastError = error as Error;
   201→        console.error(`[ImageGen] Fitting model attempt ${attempt + 1} failed:`, error);
   202→
   203→        // Don't retry on certain errors
   204→        if (this.isNonRetryableError(error)) {
   205→          break;
   206→        }
   207→      }
   208→    }
   209→
   210→    // All retries failed
   211→    return {
   212→      success: false,
   213→      error: 'GENERATION_FAILED',
   214→      message: 'Unable to generate fitting model image. Please try again later.',
   215→    };
   216→  }
   217→
   218→  /**
   219→   * Makes multimodal API request to OpenRouter for fitting model generation
   220→   *
   221→   * @private
   222→   */
   223→  private async makeFittingModelRequest(
   224→    prompt: string,
   225→    referenceImageBase64: string
   226→  ): Promise<ImageGenerationResponse> {
   227→    // Build multimodal request body with text + image content
   228→    // OpenRouter expects text first, then images (per documentation)
   229→    const requestBody = {
   230→      model: OPENROUTER_CONFIG.model,
   231→      messages: [
   232→        {
   233→          role: 'user',
   234→          content: [
   235→            {
   236→              type: 'text',
   237→              text: prompt,
   238→            },
   239→            {
   240→              type: 'image_url',
   241→              image_url: {
   242→                url: referenceImageBase64,
   243→              },
   244→            },
   245→          ],
   246→        },
   247→      ],
   248→      modalities: ['text', 'image'], // Required for image generation output
   249→      max_tokens: 4096,
   250→    };
   251→
   252→    console.log('[ImageGen] Sending fitting model request to OpenRouter:', {
   253→      model: requestBody.model,
   254→      promptLength: prompt.length,
   255→      hasReferenceImage: true,
   256→    });
   257→
   258→    // Create abort controller with extended timeout for fitting model
   259→    const controller = new AbortController();
   260→    const timeoutId = setTimeout(
   261→      () => controller.abort(),
   262→      OpenRouterImageClient.FITTING_MODEL_CONFIG.timeout
   263→    );
   264→
   265→    try {
   266→      const response = await fetch(`${OPENROUTER_CONFIG.baseUrl}/chat/completions`, {
   267→        method: 'POST',
   268→        headers: {
   269→          'Content-Type': 'application/json',
   270→          Authorization: `Bearer ${this.apiKey}`,
   271→          'HTTP-Referer': 'https://ootday.com',
   272→          'X-Title': 'OOTDay Fashion Assistant',
   273→        },
   274→        body: JSON.stringify(requestBody),
   275→        signal: controller.signal,
   276→      });
   277→
   278→      clearTimeout(timeoutId);
   279→
   280→      if (!response.ok) {
   281→        const errorData = await response.json().catch(() => ({}));
   282→        throw new Error(
   283→          `OpenRouter API error: ${response.status} - ${errorData.error?.message || response.statusText}`
   284→        );
   285→      }
   286→
   287→      const data = await response.json();
   288→
   289→      // Parse response and extract image using existing method
   290→      const imageData = this.parseImageResponse(data);
   291→
   292→      return {
   293→        success: true,
   294→        imageBase64: imageData.base64,
   295→        imageUrl: imageData.url,
   296→        metadata: {
   297→          model: OPENROUTER_CONFIG.model,
   298→          generatedAt: new Date().toISOString(),
   299→          prompt: prompt,
   300→        },
   301→        message: 'Fitting model image generated successfully',
   302→      };
   303→    } catch (error) {
   304→      clearTimeout(timeoutId);
   305→
   306→      if (error instanceof Error) {
   307→        if (error.name === 'AbortError') {
   308→          throw new Error('Request timeout - fitting model generation took too long');
   309→        }
   310→        throw error;
   311→      }
   312→
   313→      throw new Error('Unknown error during fitting model generation');
   314→    }
   315→  }
   316→
   317→  /**
   318→   * Makes the actual API request to OpenRouter
   319→   *
   320→   * @private
   321→   */
   322→  private async makeRequest(
   323→    description: string,
   324→    options?: ImageGenerationRequest['style']
   325→  ): Promise<ImageGenerationResponse> {
   326→    // Build fashion-specific prompt
   327→    const prompt = this.buildFashionPrompt(description, options);
   328→
   329→    // Create request payload - OpenRouter image generation requires messages format with modalities
   330→    const requestBody = {
   331→      model: OPENROUTER_CONFIG.model,
   332→      messages: [
   333→        {
   334→          role: 'user',
   335→          content: prompt,
   336→        },
   337→      ],
   338→      modalities: ['text', 'image'], // Required for image generation
   339→      max_tokens: 4096, // For image generation
   340→    };
   341→
   342→    console.log('[ImageGen] Sending request to OpenRouter:', {
   343→      model: requestBody.model,
   344→      promptLength: prompt.length,
   345→    });
   346→
   347→    // Create abort controller for timeout
   348→    const controller = new AbortController();
   349→    const timeoutId = setTimeout(() => controller.abort(), OPENROUTER_CONFIG.timeout);
   350→
   351→    try {
   352→      const response = await fetch(`${OPENROUTER_CONFIG.baseUrl}/chat/completions`, {
   353→        method: 'POST',
   354→        headers: {
   355→          'Content-Type': 'application/json',
   356→          Authorization: `Bearer ${this.apiKey}`,
   357→          'HTTP-Referer': 'https://ootday.com', // Optional: Your site URL
   358→          'X-Title': 'OOTDay Fashion Assistant', // Optional: Your app name
   359→        },
   360→        body: JSON.stringify(requestBody),
   361→        signal: controller.signal,
   362→      });
   363→
   364→      clearTimeout(timeoutId);
   365→
   366→      if (!response.ok) {
   367→        const errorData = await response.json().catch(() => ({}));
   368→        throw new Error(
   369→          `OpenRouter API error: ${response.status} - ${errorData.error?.message || response.statusText}`
   370→        );
   371→      }
   372→
   373→      const data = await response.json();
   374→
   375→      // Parse response and extract image
   376→      // Note: Gemini 2.5 Flash Preview returns image as base64 in content
   377→      const imageData = this.parseImageResponse(data);
   378→
   379→      return {
   380→        success: true,
   381→        imageBase64: imageData.base64,
   382→        imageUrl: imageData.url,
   383→        metadata: {
   384→          model: OPENROUTER_CONFIG.model,
   385→          generatedAt: new Date().toISOString(),
   386→          prompt: prompt,
   387→        },
   388→        message: 'Image generated successfully',
   389→      };
   390→    } catch (error) {
   391→      clearTimeout(timeoutId);
   392→
   393→      if (error instanceof Error) {
   394→        if (error.name === 'AbortError') {
   395→          throw new Error('Request timeout - image generation took too long');
   396→        }
   397→        throw error;
   398→      }
   399→
   400→      throw new Error('Unknown error during image generation');
   401→    }
   402→  }
   403→
   404→  /**
   405→   * Builds fashion-specific prompt for image generation
   406→   * Applies professional photography style and Thai fashion aesthetic
   407→   *
   408→   * @private
   409→   */
   410→  private buildFashionPrompt(
   411→    description: string,
   412→    options?: ImageGenerationRequest['style']
   413→  ): string {
   414→    const photographyStyle = options?.photographyStyle || 'editorial fashion';
   415→    const composition = options?.composition || 'full-body model shoot';
   416→    const lighting = options?.lighting || 'studio';
   417→    const aesthetic = options?.aestheticContext || 'modern international';
   418→
   419→    // Fashion-specific prompt template
   420→    const promptTemplate = `
   421→Generate a high-quality fashion photograph of a real person wearing the outfit:
   422→
   423→OUTFIT DESCRIPTION: ${description}
   424→
   425→PHOTOGRAPHY STYLE: ${photographyStyle}
   426→COMPOSITION: ${composition}
   427→LIGHTING: ${lighting}
   428→AESTHETIC: ${aesthetic} fashion style
   429→
   430→REQUIREMENTS:
   431→- Professional product photography quality
   432→- Clear, well-lit composition
   433→- Clean background (white or minimal)
   434→- Sharp focus on outfit details
   435→- Accurate color representation
   436→- Suitable for fashion e-commerce
   437→- Thai contemporary fashion aesthetic
   438→- Elegant and modern presentation
   439→
   440→AVOID:
   441→- Blurry or low-resolution images
   442→- Cluttered backgrounds
   443→- Poor lighting or shadows
   444→- Distorted proportions
   445→- Unrealistic colors
   446→`.trim();
   447→
   448→    return promptTemplate;
   449→  }
   450→
   451→  /**
   452→   * Parses image response from OpenRouter API
   453→   * OpenRouter returns images in an 'images' array within the assistant message
   454→   *
   455→   * @private
   456→   */
   457→  private parseImageResponse(data: any): { base64?: string; url?: string } {
   458→    // OpenRouter returns images as base64 data URLs in the 'images' array
   459→    // Format: { choices: [{ message: { content: "...", images: ["data:image/png;base64,..."] } }] }
   460→
   461→    try {
   462→      console.log('[ImageGen] Parsing response:', JSON.stringify(data).slice(0, 500));
   463→
   464→      if (data.choices && data.choices[0] && data.choices[0].message) {
   465→        const message = data.choices[0].message;
   466→
   467→        // Primary format: images array (OpenRouter standard)
   468→        if (message.images && Array.isArray(message.images) && message.images.length > 0) {
   469→          const imageData = message.images[0];
   470→          console.log('[ImageGen] Found image in images array, type:', typeof imageData);
   471→
   472→          // Images are returned as data URLs (data:image/png;base64,...)
   473→          if (typeof imageData === 'string' && imageData.startsWith('data:image')) {
   474→            return { base64: imageData };
   475→          }
   476→
