    62→ * @param request - Next.js request object
    63→ * @returns IP address string
    64→ */
    65→function getClientIP(request: NextRequest): string {
    66→  // Try various headers that might contain the real IP
    67→  const forwarded = request.headers.get('x-forwarded-for');
    68→  if (forwarded) {
    69→    return forwarded.split(',')[0].trim();
    70→  }
    71→
    72→  const realIP = request.headers.get('x-real-ip');
    73→  if (realIP) {
    74→    return realIP;
    75→  }
    76→
    77→  // Fallback to a default value
    78→  return 'unknown';
    79→}
